        "/v3/plots": {
          "get": {
            "summary": "List plots (offset/limit pagination)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts": {
          "get": {
            "summary": "List alerts (Link-header RFC5988 pagination)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/summary": {
          "get": {
            "summary": "Regional rollup stats",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/diag/stream": {
          "get": {
            "summary": "Diagnostic cursor stream",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/probes": {
          "get": {
            "summary": "List probes",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
